import json
from datetime import date, datetime, timezone
from decimal import Decimal


class Order:
    def __init__(self, oid, amount, created):
        self.oid = oid
        self.amount = amount
        self.created = created

    def to_json(self):
        return {'oid': self.oid, 'amount': str(self.amount), 'created': self.created.isoformat()}


order = Order('A-1001', Decimal('19.90'), datetime(2026, 10, 8, 12, 0, tzinfo=timezone.utc))

print("=== 直接 dumps: 三种类型都不可序列化 ===")
for label, obj in (('Decimal', order.amount), ('datetime', order.created), ('自定义类', order)):
    try:
        json.dumps({'v': obj})
    except TypeError as e:
        print("  %-8s -> TypeError: %s" % (label, str(e)[:62]))

print()
print("=== 方案 A: default= 钩子（按类型兜底）===")


def fallback(o):
    if isinstance(o, (datetime, date)):
        return o.isoformat()
    if isinstance(o, Decimal):
        return str(o)
    raise TypeError('不支持的类型: %s' % type(o).__name__)


payload = {'amount': order.amount, 'created': order.created}
print(json.dumps(payload, default=fallback, ensure_ascii=False))

print()
print("=== 方案 B: 显式 to_json（推荐：契约显式、可控）===")
print(json.dumps(order.to_json(), ensure_ascii=False))

print()
print("=== 方案 C: 自定义 JSONEncoder 子类 ===")


class OrderEncoder(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, Order):
            return o.to_json()
        if isinstance(o, Decimal):
            return str(o)
        if isinstance(o, datetime):
            return o.isoformat()
        return super().default(o)


print(json.dumps(order, cls=OrderEncoder, ensure_ascii=False))

print()
print("=== 反序列化: 类型不会自动回来 ===")
raw = json.dumps(order.to_json(), ensure_ascii=False)
back = json.loads(raw)
print("loads 结果      =", back)
print("amount 类型     =", type(back['amount']).__name__, "(str, 需自己 Decimal(...))")
print("created 类型    =", type(back['created']).__name__, "(str, 需自己 datetime.fromisoformat(...))")
print("fromisoformat   =", datetime.fromisoformat(back['created']))

print()
print("=== 结论 ===")
print("序列化策略优先级: 显式 to_json > default 钩子 > Encoder 子类; 反序列化必须显式还原类型")
